class Solution {
public:
    bool isValid(string code) {
        vector<string> st;
        int i = 0, n = code.size();

        while (i < n) {
            if (i > 0 && st.empty()) return false;
            if (code.substr(i, 9) == "<![CDATA[") {
                size_t j = code.find("]]>", i + 9);
                if (j == string::npos) return false;
                i = j + 3;
            } else if (code.substr(i, 2) == "</") {
                size_t j = code.find(">", i + 2);
                if (j == string::npos) return false;
                string tag = code.substr(i + 2, j - (i + 2));
                if (st.empty() || st.back() != tag) return false;
                st.pop_back();
                i = j + 1;
            } else if (code[i] == '<') {
                size_t j = code.find(">", i + 1);
                if (j == string::npos) return false;
                string tag = code.substr(i + 1, j - (i + 1));
                if (tag.size() < 1 || tag.size() > 9) return false;
                for (char c : tag) {
                    if (!isupper(c)) return false;
                }
                st.push_back(tag);
                i = j + 1;
            } else {
                i++;
            }
        }
        return st.empty();
    }
};

class Solution {
    public boolean isValid(String code) {
        Stack<String> stack = new Stack<>();
        int i = 0, n = code.length();

        while (i < n) {
            if (i > 0 && stack.isEmpty()) return false;
            if (code.startsWith("<![CDATA[", i)) {
                int j = code.indexOf("]]>", i + 9);
                if (j == -1) return false;
                i = j + 3;
            } else if (code.startsWith("</", i)) {
                int j = code.indexOf(">", i + 2);
                if (j == -1) return false;
                String tag = code.substring(i + 2, j);
                if (stack.isEmpty() || !stack.peek().equals(tag)) return false;
                stack.pop();
                i = j + 1;
            } else if (code.charAt(i) == '<') {
                int j = code.indexOf(">", i + 1);
                if (j == -1) return false;
                String tag = code.substring(i + 1, j);
                if (tag.length() < 1 || tag.length() > 9) return false;
                for (char c : tag.toCharArray()) {
                    if (!Character.isUpperCase(c)) return false;
                }
                stack.push(tag);
                i = j + 1;
            } else {
                i++;
            }
        }
        return stack.isEmpty();
    }
}

var isValid = function(code) {
    const stack = [];
    let i = 0, n = code.length;

    while (i < n) {
        if (i > 0 && stack.length === 0) return false;
        if (code.startsWith("<![CDATA[", i)) {
            const j = code.indexOf("]]>", i + 9);
            if (j === -1) return false;
            i = j + 3;
        } else if (code.startsWith("</", i)) {
            const j = code.indexOf(">", i + 2);
            if (j === -1) return false;
            const tag = code.slice(i + 2, j);
            if (stack.length === 0 || stack[stack.length - 1] !== tag) return false;
            stack.pop();
            i = j + 1;
        } else if (code[i] === "<") {
            const j = code.indexOf(">", i + 1);
            if (j === -1) return false;
            const tag = code.slice(i + 1, j);
            if (tag.length < 1 || tag.length > 9 || !/^[A-Z]+$/.test(tag)) return false;
            stack.push(tag);
            i = j + 1;
        } else {
            i++;
        }
    }
    return stack.length === 0;
};
